/**
 * Returns list of allowed kitchen IDs for a given supplier ID or supplier code
 */
export const getKitchenIdsForSupplier = (supplierIdOrCode: number | string): number[] => {
  if (typeof supplierIdOrCode === 'number') {
    return SUPPLIER_KITCHEN_PERMISSIONS
      .filter(p => p.supplierId === supplierIdOrCode)
      .map(p => p.kitchenId);
  }
  const codeUpper = String(supplierIdOrCode).toUpperCase();
  return SUPPLIER_KITCHEN_PERMISSIONS
    .filter(p => p.supplierCode === codeUpper)
    .map(p => p.kitchenId);
};

/**
 * Returns allowed kitchens list for a given supplier
 */
export const filterKitchensForSupplier = <T extends { id: number }>(kitchens: T[], supplierIdOrCode: number | string): T[] => {
  const allowedIds = new Set(getKitchenIdsForSupplier(supplierIdOrCode));
  if (allowedIds.size === 0) return kitchens;
  return kitchens.filter(k => allowedIds.has(k.id));
};
